/// Structured parking fees v2 (docs/designs/2026-10-26-parking-conditions-and-fees.md
/// §2), shared by the app and the admin site; pure Dart so both import the
/// same rules. The JSON shape matches the `fee` column (`valid_fee()`,
/// generated by tool/gen_contract_sql.py from
/// supabase/functions/_shared/parking_contract.json) and `validFee` in
/// supabase/functions/_shared/fee.ts; [feeNoteOf] writes the sentences of
/// `fee_note_of()` and `feeNoteOf` there. parking_contract_cases.json pins
/// both for every side (test/fee_contract_test.dart).
library;

import 'dart:convert';

import 'parking_condition.dart'
    show feeContract, scheduleWeekdays, timeOptionalPair, validSlotTimes;

/// How a vehicle pays. Heavy bikes may also follow another vehicle's rate.
enum FeeMode {
  free('free'),

  /// 依現場公告: still accepted so older builds' reports are not refused,
  /// but read as unconfirmed (§7 item 15) and never written by new builds.
  posted('posted'),
  hourly('hourly'),
  perVisit('per_visit'),
  daily('daily'),

  /// Rates that differ by time of day and day of the week (§2.2).
  byTime('by_time'),
  sameAsScooter('same_as_scooter'),
  sameAsCar('same_as_car');

  const FeeMode(this.wire);

  /// The value stored as `mode`.
  final String wire;

  /// Modes that follow another vehicle's rate, only for heavy bikes.
  bool get follows => this == sameAsScooter || this == sameAsCar;
}

/// When a daily cap or a daily charge starts over; null is unconfirmed.
enum CapReset {
  calendarDay('calendar_day'),
  rolling24h('rolling_24h'),
  perEntry('per_entry');

  const CapReset(this.wire);
  final String wire;
}

/// Whether a per-visit charge starts again after midnight (§2.5); null is
/// unconfirmed, never 不另計.
enum Renew {
  none('none'),
  midnight('midnight');

  const Renew(this.wire);
  final String wire;
}

/// How a stay crossing into another per-visit period is charged (§2.5);
/// null is unconfirmed.
enum CrossPeriod {
  eachPeriod('each_period'),
  entryOnly('entry_only');

  const CrossPeriod(this.wire);
  final String wire;
}

T? _wire<T extends Enum>(List<T> values, Object? wire, String Function(T) of) =>
    values.where((v) => of(v) == wire).firstOrNull;

int? _int(Object? v) => v is num ? v.toInt() : null;

/// Paid extensions of a per-visit stay: each [amount], at most [maxTimes],
/// [minutes] each (null is unconfirmed).
class FeeExtension {
  const FeeExtension({
    required this.amount,
    required this.maxTimes,
    this.minutes,
  });
  final int amount, maxTimes;
  final int? minutes;

  Map<String, Object> toJson() => {
    'amount': amount,
    'max_times': maxTimes,
    'minutes': ?minutes,
  };
}

/// One period of a by-time rate: the days (`all`, `weekday`, `holiday` or a
/// list of weekdays), [from]–[to] (both null: all day; from > to crosses
/// midnight) and its [rate], which neither follows nor nests by_time.
class FeePeriod {
  const FeePeriod({required this.days, this.from, this.to, required this.rate});
  final Object days;
  final String? from, to;
  final Rate rate;

  Map<String, Object> toJson() => {
    'days': days,
    'from': ?from,
    'to': ?to,
    'rate': rate.toJson(),
  };
}

/// Whether [json] is one vehicle's rate the column accepts (§2.2): the
/// mode's keys only, every value in range. A period's rate ([nested]) may
/// not follow or be by_time; only heavy bikes follow.
bool validRate(Object? json, String vehicle, {bool nested = false}) {
  if (json is! Map || json['mode'] is! String) return false;
  final mode = json['mode'] as String;
  final follow = feeContract['follow']! as Map<String, Object?>;
  if ((follow['modes']! as List).contains(mode)) {
    return !nested &&
        (follow['vehicles']! as List).contains(vehicle) &&
        _validFields(json, {
          'required': const <String, Object?>{},
          'optional': follow['optional'],
        }, vehicle);
  }
  final modes = feeContract['modes']! as Map<String, Object?>;
  final periods = feeContract['periods']! as Map<String, Object?>;
  if (!modes.containsKey(mode)) return false;
  if (nested && !(periods['nested_modes']! as List).contains(mode)) {
    return false;
  }
  return _validFields(json, modes[mode]! as Map<String, Object?>, vehicle);
}

bool _whole(Object? v, num min, num max) =>
    v is num && v.isFinite && v == v.truncate() && v >= min && v <= max;

bool _validFields(
  Map<Object?, Object?> json,
  Map<String, Object?> spec,
  String vehicle,
) {
  final required = spec['required']! as Map;
  final optional = spec['optional']! as Map;
  final enums = feeContract['enums']! as Map<String, Object?>;
  for (final MapEntry(:key, :value) in json.entries) {
    if (key == 'mode') continue;
    final field = required[key] ?? optional[key];
    switch (field) {
      case null:
        return false;
      case {'min': final num min, 'max': final Object max}:
        final hi = max is String ? json[max] : max;
        if (!_whole(hi, 0, 1e9) || !_whole(value, min, hi as num)) {
          return false;
        }
      case final String name when enums.containsKey(name):
        if (!(enums[name]! as List).contains(value)) return false;
      case 'extension':
        if (value is! Map ||
            value.containsKey('mode') ||
            !_validFields(
              value,
              feeContract['extension']! as Map<String, Object?>,
              vehicle,
            )) {
          return false;
        }
      case 'periods':
        final p = feeContract['periods']! as Map<String, Object?>;
        final keys = p['keys']! as List;
        if (value is! List ||
            value.isEmpty ||
            value.length > (p['max_entries']! as int) ||
            !value.every(
              (e) =>
                  e is Map &&
                  e.keys.every(keys.contains) &&
                  keys.every(
                    (k) => e.containsKey(k) || timeOptionalPair.contains(k),
                  ) &&
                  validSlotTimes(e) &&
                  validRate(e['rate'], vehicle, nested: true),
            )) {
          return false;
        }
      default:
        return false;
    }
  }
  return required.keys.every(json.containsKey);
}

/// Whether [json] is a fee the column accepts: a rate per known vehicle,
/// within the size bound (read as UTF-8 JSON, close to the column's).
bool validFee(Object? json) =>
    json is Map &&
    utf8.encode(jsonEncode(json)).length <=
        (feeContract['max_bytes']! as int) &&
    json.entries.every(
      (e) =>
          (feeContract['vehicles']! as List).contains(e.key) &&
          validRate(e.value, e.key as String),
    );

/// One vehicle's rate. Amounts and caps are whole yuan, periods minutes.
class Rate {
  const Rate(
    this.mode, {
    this.amount,
    this.perMinutes,
    this.dailyCap,
    this.maxMinutes,
    this.unitMinutes,
    this.freeMinutes,
    this.capReset,
    this.renew,
    this.extension,
    this.periods,
    this.crossPeriod,
    this.factorPct,
  });
  final FeeMode mode;
  final int? amount, perMinutes, dailyCap, maxMinutes;

  /// Hourly: the billing unit and the free first minutes (首段 0 元).
  final int? unitMinutes, freeMinutes;
  final CapReset? capReset;
  final Renew? renew;
  final FeeExtension? extension;
  final List<FeePeriod>? periods;
  final CrossPeriod? crossPeriod;

  /// A follow's factor, 200 for twice; null is once.
  final int? factorPct;

  /// The rate in [json], or null when it is not one the column accepts:
  /// an unknown mode or key, or any value out of range, optional or not.
  static Rate? fromJson(Object? json, {required bool heavy}) =>
      validRate(json, heavy ? 'heavy' : 'scooter')
      ? _build(json! as Map)
      : null;

  static Rate _build(Map<Object?, Object?> json) {
    final mode = _wire(FeeMode.values, json['mode'], (m) => m.wire)!;
    final ext = json['extension'];
    final periods = json['periods'];
    return Rate(
      mode,
      amount: _int(json['amount']),
      perMinutes: _int(json['per_minutes']),
      dailyCap: _int(json['daily_cap']),
      maxMinutes: _int(json['max_minutes']),
      unitMinutes: _int(json['unit_minutes']),
      freeMinutes: _int(json['free_minutes']),
      capReset: _wire(CapReset.values, json['cap_reset'], (v) => v.wire),
      renew: _wire(Renew.values, json['renew'], (v) => v.wire),
      extension: ext is Map
          ? FeeExtension(
              amount: _int(ext['amount'])!,
              maxTimes: _int(ext['max_times'])!,
              minutes: _int(ext['minutes']),
            )
          : null,
      periods: periods is List
          ? [
              for (final p in periods.cast<Map<Object?, Object?>>())
                FeePeriod(
                  days: p['days'] is List
                      ? List<String>.from(p['days'] as List)
                      : p['days'] as String,
                  from: p['from'] as String?,
                  to: p['to'] as String?,
                  rate: _build(p['rate'] as Map),
                ),
            ]
          : null,
      crossPeriod: _wire(
        CrossPeriod.values,
        json['cross_period'],
        (v) => v.wire,
      ),
      factorPct: _int(json['factor_pct']),
    );
  }

  /// Whether the mode has every value it needs to be shown or stored.
  bool get complete => switch (mode) {
    FeeMode.hourly => amount != null && perMinutes != null,
    FeeMode.perVisit || FeeMode.daily => amount != null,
    FeeMode.byTime => periods?.isNotEmpty ?? false,
    _ => true,
  };

  /// Only the keys this mode uses, as the column requires.
  Map<String, Object> toJson() => {
    'mode': mode.wire,
    if (mode == FeeMode.hourly) ...{
      'amount': ?amount,
      'per_minutes': ?perMinutes,
      'unit_minutes': ?unitMinutes,
      'free_minutes': ?freeMinutes,
      'daily_cap': ?dailyCap,
      'cap_reset': ?capReset?.wire,
    },
    if (mode == FeeMode.perVisit) ...{
      'amount': ?amount,
      'max_minutes': ?maxMinutes,
      'renew': ?renew?.wire,
      'extension': ?extension?.toJson(),
    },
    if (mode == FeeMode.daily) ...{
      'amount': ?amount,
      'cap_reset': ?capReset?.wire,
    },
    if (mode == FeeMode.byTime) ...{
      'periods': ?periods?.map((p) => p.toJson()).toList(),
      'cross_period': ?crossPeriod?.wire,
    },
    if (mode.follows) 'factor_pct': ?factorPct,
  };

  /// The rate as riders read it, e.g. 每小時 20 元，當日上限 100 元（零時重算）.
  /// A follow names what it follows (an editor label); [Fee.textOf] and
  /// [feeNoteOf] show the amounts worked out instead.
  String get text => switch (mode) {
    FeeMode.posted => '依現場公告',
    FeeMode.sameAsScooter => '比照機車費率',
    FeeMode.sameAsCar => '比照汽車費率',
    _ => _rateText(toJson(), 100) ?? '',
  };

  @override
  bool operator ==(Object other) =>
      other is Rate && jsonEncode(other.toJson()) == jsonEncode(toJson());

  @override
  int get hashCode => jsonEncode(toJson()).hashCode;
}

/// A rate per vehicle; a null vehicle is unconfirmed.
class Fee {
  const Fee({this.scooter, this.heavy, this.car});
  final Rate? scooter, heavy, car;

  /// The fee in [json]; vehicles whose rate is not valid, or is `posted`,
  /// read as unconfirmed.
  static Fee fromJson(Object? json) => json is Map
      ? Fee(
          scooter: _known(Rate.fromJson(json['scooter'], heavy: false)),
          heavy: _known(Rate.fromJson(json['heavy'], heavy: true)),
          car: _known(Rate.fromJson(json['car'], heavy: false)),
        )
      : const Fee();

  static Rate? _known(Rate? rate) => rate?.mode == FeeMode.posted ? null : rate;

  /// The fee in [json] when all of it is one the column accepts, else null.
  /// Unlike [fromJson], an unknown vehicle or a bad rate is not dropped
  /// silently, so a value from elsewhere (a report) is taken whole or not
  /// at all. A `posted` rate is accepted and reads as unconfirmed.
  static Fee? tryParse(Object? json) =>
      json is Map && validFee(json) ? fromJson(json) : null;

  bool get isEmpty => scooter == null && heavy == null && car == null;

  /// Whether every rate given has its amounts, in the column's ranges.
  bool get valid => validFee(toJson());

  Map<String, Object> toJson() => {
    if (scooter case final rate?) 'scooter': rate.toJson(),
    if (heavy case final rate?) 'heavy': rate.toJson(),
    if (car case final rate?) 'car': rate.toJson(),
  };

  /// This fee with the given vehicles replaced; the others, the car's
  /// included, stay as they are.
  Fee copyWith({Rate? Function()? scooter, Rate? Function()? heavy}) => Fee(
    scooter: scooter == null ? this.scooter : scooter(),
    heavy: heavy == null ? this.heavy : heavy(),
    car: car,
  );

  /// One vehicle's rate as riders read it, a heavy follow with its amounts
  /// worked out (#140); null when unconfirmed, including a follow of an
  /// unconfirmed vehicle.
  String? textOf(String vehicle) {
    final json = toJson();
    if (vehicle == 'heavy') return _heavyText(json).text;
    return _rateText(json[vehicle], 100);
  }

  /// One line for every vehicle, as stored in `fee_note`; empty when no
  /// vehicle is known.
  String get summary => isEmpty ? '' : feeNoteOf(this);

  @override
  bool operator ==(Object other) =>
      other is Fee &&
      other.scooter == scooter &&
      other.heavy == heavy &&
      other.car == car;

  @override
  int get hashCode => Object.hash(scooter, heavy, car);
}

/// A spot's stored `fee` as a [Fee], or null when it holds no structured
/// data: not an object, or `{}` (#114, as fee_note_matches() reads it).
/// Without one, riders read `fee_note`.
Fee? structuredFee(Object? json) =>
    json is Map && json.isNotEmpty ? Fee.fromJson(json) : null;

/// The `fee_note` text stored beside [fee] (§2.5): the known vehicles as
/// 機車…；大型重機…；汽車…, then 大型重機費率未確認 when the heavy rate is
/// unknown; the default note when no vehicle is known.
String feeNoteOf(Fee? fee) => feeNoteOfJson(fee?.toJson());

/// [feeNoteOf] of a fee as JSON, as `fee_note_of()` takes it.
String feeNoteOfJson(Object? fee) {
  final f = fee is Map ? fee : const <Object?, Object?>{};
  final s = _rateText(f['scooter'], 100), c = _rateText(f['car'], 100);
  final (:text, :unprovided) = _heavyText(f);
  if (s == null && text == null && c == null && !unprovided) {
    return defaultFeeNote;
  }
  return [
    if (s != null) '機車$s',
    if (text != null || unprovided) '大型重機${text ?? '費率未提供'}',
    if (c != null) '汽車$c',
    if (text == null && !unprovided) '大型重機費率未確認',
  ].join('；');
}

/// The note of a spot without a known fee.
const defaultFeeNote = '請依現場公告';

/// The longest [feeNoteOf] the contract allows (§2.5), as
/// supabase/functions/_shared/fee_note_limit.json holds it; the spot
/// tables' fee_note check. Free text stays within [freeFeeNoteMaxLength].
const feeNoteMaxLength = 1909;
const freeFeeNoteMaxLength = 200;

({String? text, bool unprovided}) _heavyText(Map<Object?, Object?> f) {
  final heavy = f['heavy'];
  if (heavy is Map &&
      (heavy['mode'] == 'same_as_scooter' || heavy['mode'] == 'same_as_car')) {
    final target = heavy['mode'] == 'same_as_scooter' ? f['scooter'] : f['car'];
    final text = _rateText(target, _int(heavy['factor_pct']) ?? 100);
    return (text: text, unprovided: text == null);
  }
  return (text: _rateText(heavy, 100), unprovided: false);
}

const _resets = {
  'calendar_day': '零時重算',
  'rolling_24h': '停滿 24 小時重算',
  'per_entry': '每次進場重算',
};
const _dayMasks = {'all': 127, 'weekday': 31, 'holiday': 96};
const _dayNames = '一二三四五六日';

/// Whole yuan at [pct] percent, with at most two decimals: 22.5, 41.25.
/// An incomplete rate (an editor's draft) reads its missing amount as 0.
String _money(Object? amount, int pct) {
  final v = (_int(amount) ?? 0) * pct, whole = v ~/ 100, rem = v % 100;
  if (rem == 0) return '$whole';
  if (rem % 10 == 0) return '$whole.${rem ~/ 10}';
  return '$whole.${rem.toString().padLeft(2, '0')}';
}

String _span(Object? v) {
  final m = _int(v)!;
  return m % 60 == 0 ? '${m ~/ 60} 小時' : '$m 分鐘';
}

String _every(Object? v) {
  final m = _int(v) ?? 60;
  return m == 60
      ? '每小時'
      : m % 60 == 0
      ? '每 ${m ~/ 60} 小時'
      : '每 $m 分鐘';
}

int _dayMask(Object? days) => days is String
    ? _dayMasks[days]!
    : (days! as List).fold(
        0,
        (m, d) => m | (1 << scheduleWeekdays.indexOf(d as String)),
      );

String _dayLabel(int mask) => switch (mask) {
  127 => '每天',
  31 => '平日',
  96 => '假日',
  _ => [
    for (var i = 0; i < 7; i++)
      if (mask & (1 << i) != 0) '週${_dayNames[i]}',
  ].join('、'),
};

/// One rate's words at [pct] percent, or null when it reads as unconfirmed
/// (posted, by_time of posted periods only, or a follow out of place).
String? _rateText(Object? r, int pct) {
  if (r is! Map) return null;
  switch (r['mode']) {
    case 'free':
      return '免費';
    case 'hourly':
      var t = '${_every(r['per_minutes'])} ${_money(r['amount'], pct)} 元';
      if (r.containsKey('free_minutes')) {
        t = '首 ${_span(r['free_minutes'])} 0 元，之後$t';
      }
      if (r.containsKey('unit_minutes')) {
        t += '（以 ${_span(r['unit_minutes'])}計）';
      }
      if (r.containsKey('daily_cap')) {
        final reset = _resets[r['cap_reset']] ?? '上限計算方式未確認';
        t += '，當日上限 ${_money(r['daily_cap'], pct)} 元（$reset）';
      }
      return t;
    case 'per_visit':
      String t;
      if (_int(r['amount']) == 0 && r.containsKey('max_minutes')) {
        t = '首 ${_span(r['max_minutes'])} 0 元';
      } else {
        final notes = [
          if (r.containsKey('max_minutes')) '${_span(r['max_minutes'])}內',
          if (!r.containsKey('renew')) '隔日是否另計未確認',
        ];
        t = '每次 ${_money(r['amount'], pct)} 元';
        if (notes.isNotEmpty) t += '（${notes.join('，')}）';
        if (r['renew'] == 'midnight') t += '，隔日另計';
        if (r['renew'] == 'none') {
          t += r.containsKey('max_minutes') ? '，有效時間內只收一次' : '，停多久都只收一次';
        }
      }
      final ext = r['extension'];
      if (ext is Map) {
        t +=
            '，可付 ${_money(ext['amount'], pct)} 元延長 '
            '${_int(ext['max_times'])} 次';
        t += ext.containsKey('minutes')
            ? '（每次 ${_span(ext['minutes'])}）'
            : '（延長時間未確認）';
      }
      return t;
    case 'daily':
      final reset = _resets[r['cap_reset']];
      return '每日 ${_money(r['amount'], pct)} 元'
          '${reset == null ? '' : '（$reset）'}';
    case 'by_time':
      // Periods grouped by the days they cover, in order of first appearance.
      final groups = <int, List<String>>{};
      var visits = 0;
      for (final p in (r['periods'] as List).cast<Map<Object?, Object?>>()) {
        final text = _rateText(p['rate'], pct);
        if (text == null) continue;
        if ((p['rate'] as Map)['mode'] == 'per_visit') visits++;
        final from = p['from'] as String?, to = p['to'] as String?;
        final time = from == null
            ? '全天'
            : '$from–${from.compareTo(to!) < 0 ? '' : '隔日 '}$to';
        groups.putIfAbsent(_dayMask(p['days']), () => []).add('$time $text');
      }
      if (groups.isEmpty) return null;
      var t = [
        for (final MapEntry(:key, :value) in groups.entries)
          '${_dayLabel(key)}：${value.join('；')}',
      ].join('；');
      if (r.containsKey('cross_period')) {
        t += r['cross_period'] == 'each_period' ? '；跨時段分別計費' : '；依進場時段計費';
      } else if (visits >= 2) {
        t += '；跨時段計費方式未確認';
      }
      return t;
  }
  return null;
}
